mapper.select:
SELECT l.mail_log_id::TEXT AS row_id, l.template_cd, CONVERT_FROM(DECRYPT(DECODE(l.to_email,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') AS to_email, l.subject, l.status_cd, c.name AS status_name, l.error_msg, l.reg_id, TO_CHAR(l.reg_dt, 'YYYY-MM-DD HH24:MI:SS') AS reg_dt FROM mail_log l LEFT JOIN code c ON c.code_id = l.status_cd AND c.p_code_id = 'MAIL00'
AND l.status_cd = #{statusCd} AND l.template_cd = #{templateCd}
AND (l.subject LIKE '%' || #{filterKeyword} || '%' OR CONVERT_FROM(DECRYPT(DECODE(l.to_email,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8') LIKE '%' || #{filterKeyword} || '%')
ORDER BY l.mail_log_id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM mail_log l

    AND l.status_cd = #{statusCd}
    AND l.template_cd = #{templateCd}

        AND (l.subject LIKE '%' || #{filterKeyword} || '%'
             OR CONVERT_FROM(DECRYPT(DECODE(l.to_email,'HEX'),#{cryptoKey}::BYTEA,'AES'),'UTF8')
                LIKE '%' || #{filterKeyword} || '%')
